(() => {
  const key='cozy-cat-snack-bag-v1',day=()=>new Date().toLocaleDateString('sv-SE');
  const tiers=[['일반',0],['고급',2],['레어',4],['에픽',6],['전설',8]];
  let bag={items:{},daily:'',earned:0,care:0,started:false};
  try{const saved=JSON.parse(localStorage.getItem(key));if(saved){bag.daily=typeof saved.daily==='string'?saved.daily:'';for(const n of ['earned','care'])bag[n]=Number.isFinite(saved[n])?Math.max(0,Math.floor(saved[n])):0;bag.started=saved.started===true;for(const snack of snackCatalog)for(let tier=0;tier<5;tier++){const id=snack.id+':'+tier,n=saved.items?.[id];if(Number.isFinite(n))bag.items[id]=Math.max(0,Math.floor(n))}}}catch{}
  if(!bag.started){for(const snack of snackCatalog)bag.items[snack.id+':0']=3;bag.started=true}
  const dialog=document.createElement('dialog');dialog.id='snackDialog';dialog.setAttribute('aria-labelledby','snackTitle');
  dialog.innerHTML='<div class="dialog-heading"><h2 id="snackTitle">간식 보관함</h2><button aria-label="간식 선택 닫기">✕</button></div><p>먹이고 싶은 간식을 골라 주세요. 첫 선물로 다섯 종류를 3개씩 담았어요.</p><button id="snackDaily" class="fun-button">오늘의 간식 선물 · 5개 받기</button><p id="snackProgress" class="snack-note"></p><nav class="snack-tiers" aria-label="간식 등급"></nav><div class="snack-grid"></div><p id="snackMessage" role="status"></p><p class="snack-note">등급과 효과는 게임 설정이에요. 실제 제품의 품질이나 효능을 뜻하지 않아요.</p>';
  document.querySelector('main').append(dialog);dialog.querySelector('.dialog-heading button').onclick=()=>dialog.close();
  let feeding=false,currentTier=0;
  function save(){try{localStorage.setItem(key,JSON.stringify(bag))}catch{$('snackMessage').textContent='이 브라우저에서는 간식 보관함을 저장할 수 없어요.'}}
  function available(){return !state.busy&&!state.sleeping&&$('playField').hidden&&!feeding}
  function grant(count){const found=[];for(let i=0;i<count;i++){const n=++bag.earned,tier=n%10===0?4:n%5===0?3:n%3===0?2:n%2===0?1:0;const snack=snackCatalog[(n-1+Math.floor(n/10))%snackCatalog.length],id=snack.id+':'+tier;bag.items[id]=(bag.items[id]||0)+1;found.push(tiers[tier][0]+' '+snack.name)}save();$('snackMessage').textContent='🎁 획득! '+found.join(', ');return found}
  tiers.forEach(([name],index)=>{const b=document.createElement('button');b.textContent=name;b.type='button';b.onclick=()=>{currentTier=index;draw()};dialog.querySelector('.snack-tiers').append(b)});
  function draw(){dialog.querySelectorAll('.snack-tiers button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===currentTier)));$('snackDaily').disabled=bag.daily===day();$('snackDaily').textContent=bag.daily===day()?'오늘 선물 받았어요 ✓':'오늘의 간식 선물 · 5개 받기';$('snackProgress').textContent='밥·쓰다듬기 3번마다 간식 2개 · 다음 선물까지 '+(3-bag.care%3)+'번. 누적 획득 10개마다 전설 확정!';const grid=dialog.querySelector('.snack-grid');grid.replaceChildren();for(const snack of snackCatalog){const id=snack.id+':'+currentTier,count=bag.items[id]||0,tier=currentTier,bonus=tiers[tier][1];const button=document.createElement('button');button.className='snack-card tier-'+tier;button.disabled=count===0;const icon=document.createElement('span');icon.className='snack-icon';icon.textContent=snack.icon;icon.setAttribute('aria-hidden','true');const title=document.createElement('strong');title.textContent=snack.name;const desc=document.createElement('span');desc.textContent=tiers[tier][0]+' · 보유 '+count+'개';const effect=document.createElement('small');effect.textContent='배부름 +'+snack.full+' · 행복 +'+(snack.happy+bonus);const action=document.createElement('small');action.textContent=count?'1개 먹이기':'아직 없어요';button.append(icon,title,desc,effect,action);button.onclick=async()=>{if(!available()){$('snackMessage').textContent='잠에서 깨거나 하던 놀이를 마치면 간식을 줄 수 있어요.';return}if(!(bag.items[id]>0))return;feeding=true;bag.items[id]--;save();selectedSnack={...snack,happy:snack.happy+bonus,line:tiers[tier][0]+' '+snack.name+'! '+snack.line};dialog.close();try{const result=await act('treat');if(!result?.ok){bag.items[id]++;save()}}catch(error){bag.items[id]++;save();say('간식을 다시 보관했어요. 잠시 후 골라 주세요.');console.error(error)}finally{feeding=false}};grid.append(button)}}
  $('snackDaily').onclick=()=>{if(bag.daily===day())return;bag.daily=day();grant(5);draw()};
  const previousAct=act;act=async action=>{const result=await previousAct(action);if(result.ok&&(action==='meal'||action==='pet')){bag.care++;if(bag.care%3===0){grant(2);say('🎁 돌봄 고마워! 간식 2개를 보관함에 넣었어요.')}save();if(dialog.open)draw()}return result};
  $('chooseSnack').onclick=()=>{draw();$('snackMessage').textContent=available()?'간식을 고르면 1개를 꺼내 먹어요.':'잠에서 깨거나 하던 일을 마친 뒤 골라 주세요.';dialog.showModal()};save();
})();
